/** Runs the whole BFS against the live row at open time and returns the deduplicated (subj, obj) pair list. */
@Experimental
final class GeneralPathEvaluation {
	private final RowState row;
	private final GeneralPathPlan plan;
	private long[] pairs = new long[16];
	private int pairCount;

	GeneralPathEvaluation(RowState row, GeneralPathPlan plan) {
		this.row = row;
		this.plan = plan;
	}

	long[] evaluate(long subj, long obj) throws IOException {
		if (subj != UNKNOWN) {
			LongHashSet reached = reachableFrom(subj, true);
			if (obj != UNKNOWN) {
				boolean identity = plan.minLength == 0L && ZeroLengthPathPlan.sameTerm(row, subj, obj);
				if (identity || reached.contains(obj)) {
					addPair(subj, obj);
				}
			} else {
				if (plan.minLength == 0L) {
					addPair(subj, subj);
				}
				emitReached(subj, reached, true);
			}
		} else if (obj != UNKNOWN) {
			if (plan.minLength == 0L) {
				addPair(obj, obj);
			}
			emitReached(obj, reachableFrom(obj, false), false);
		} else {
			evaluateBothFree();
		}
		return Arrays.copyOf(pairs, pairCount * 2);
	}

	private void emitReached(long origin, LongHashSet reached, boolean forward) {
		long[] nodes = reached.values();
		for (long node : nodes) {
			if (plan.minLength == 0L && node == origin) {
				continue; // the identity pair was already emitted store-free
			}
			if (forward) {
				addPair(origin, node);
			} else {
				addPair(node, origin);
			}
		}
	}

	private void evaluateBothFree() throws IOException {
		boolean sameEndpoint = plan.subjSlot == plan.objSlot;
		LongHashSet identitySeen = new LongHashSet(64);
		long[] identityContexts = identityContexts();
		if (plan.minLength == 0L && (identityContexts == null || identityContexts.length > 0)) {
			// zero-length identities: every distinct node occurring as subject or object of a scoped statement
			try (NativeLmdbQuerySource.NativeProbe probe = row.source.newProbe()) {
				int scopes = identityContexts == null ? 1 : identityContexts.length;
				for (int scope = 0; scope < scopes; scope++) {
					long ctx = identityContexts == null ? UNKNOWN : identityContexts[scope];
					RecordIterator statements = probe.open(UNKNOWN, UNKNOWN, UNKNOWN, ctx);
					try {
						long[] quad;
						while ((quad = statements.next()) != null) {
							if (identitySeen.add(quad[TripleIndex.SUBJ_IDX])) {
								addPair(quad[TripleIndex.SUBJ_IDX], quad[TripleIndex.SUBJ_IDX]);
							}
							if (identitySeen.add(quad[TripleIndex.OBJ_IDX])) {
								addPair(quad[TripleIndex.OBJ_IDX], quad[TripleIndex.OBJ_IDX]);
							}
						}
					} finally {
						statements.close();
					}
				}
			}
		}
		LongHashSet starts = new LongHashSet(64);
		collectStarts(starts);
		for (long start : starts.values()) {
			LongHashSet reached = reachableFrom(start, true);
			if (sameEndpoint) {
				if (plan.minLength >= 1L && reached.contains(start)) {
					addPair(start, start);
				}
				continue;
			}
			for (long node : reached.values()) {
				if (plan.minLength == 0L && node == start) {
					continue; // identity pairs came from the enumeration phase
				}
				addPair(start, node);
			}
		}
	}

	private long[] identityContexts() {
		if (plan.ctxSlot >= 0) {
			long bound = row.slots[plan.ctxSlot];
			if (bound != UNKNOWN) {
				return new long[] { bound };
			}
		}
		return plan.ctxIds;
	}

	private void collectStarts(LongHashSet starts) throws IOException {
		int mark = row.mark();
		try (RowCursor cursor = plan.step.open(row)) {
			while (cursor.next()) {
				long start = row.slots[plan.stepSubjSlot];
				if (start != UNKNOWN) {
					starts.add(start);
				}
			}
		} finally {
			row.rollback(mark);
		}
	}

	/**
	 * The endpoints reachable by a walk of length ≥ minLength (≥ 1 when minLength is 0 — the identity is handled by the
	 * caller): level-set composition for the exact-minimum prefix, then plain reachability expansion.
	 */
	private LongHashSet reachableFrom(long origin, boolean forward) throws IOException {
		long seedSteps = Math.max(1L, plan.minLength);
		LongHashSet current = new LongHashSet(16);
		current.add(origin);
		for (long k = 0; k < seedSteps; k++) {
			LongHashSet next = new LongHashSet(Math.max(16, current.size));
			for (long node : current.values()) {
				expand(node, forward, next);
			}
			current = next;
			if (current.size == 0) {
				return current;
			}
		}
		LongHashSet reached = new LongHashSet(Math.max(16, current.size));
		long[] queue = new long[Math.max(16, current.size)];
		int queueSize = 0;
		for (long node : current.values()) {
			if (reached.add(node)) {
				queue = push(queue, queueSize++, node);
			}
		}
		LongHashSet neighbors = new LongHashSet(16);
		for (int head = 0; head < queueSize; head++) {
			neighbors.clear();
			expand(queue[head], forward, neighbors);
			for (long node : neighbors.values()) {
				if (reached.add(node)) {
					queue = push(queue, queueSize++, node);
				}
			}
		}
		return reached;
	}

	/** One step evaluation against the live row; step-internal bindings roll back before returning. */
	private void expand(long node, boolean forward, LongHashSet into) throws IOException {
		int nearSlot = forward ? plan.stepSubjSlot : plan.stepObjSlot;
		int farSlot = forward ? plan.stepObjSlot : plan.stepSubjSlot;
		int mark = row.mark();
		if (!row.bind(nearSlot, node)) {
			row.rollback(mark);
			return;
		}
		try (RowCursor cursor = plan.step.open(row)) {
			while (cursor.next()) {
				long far = row.slots[farSlot];
				if (far != UNKNOWN) {
					into.add(far);
				}
			}
		} finally {
			row.rollback(mark);
		}
	}

	private static long[] push(long[] queue, int size, long value) {
		if (size == queue.length) {
			queue = Arrays.copyOf(queue, queue.length * 2);
		}
		queue[size] = value;
		return queue;
	}

	private void addPair(long subj, long obj) {
		if (pairCount * 2 == pairs.length) {
			pairs = Arrays.copyOf(pairs, pairs.length * 2);
		}
		pairs[pairCount * 2] = subj;
		pairs[pairCount * 2 + 1] = obj;
		pairCount++;
	}
}

/** Emits the materialized pairs, binding whichever endpoint slots were free at open. */
@Experimental
final class GeneralPathPairCursor implements RowCursor {
	private final RowState row;
	private final GeneralPathPlan plan;
	private final long[] pairs;
	private final boolean subjWasBound;
	private final boolean objWasBound;
	private int position;
	private int mark = -1;

	GeneralPathPairCursor(RowState row, GeneralPathPlan plan, long[] pairs, boolean subjWasBound,
			boolean objWasBound) {
		this.row = row;
		this.plan = plan;
		this.pairs = pairs;
		this.subjWasBound = subjWasBound;
		this.objWasBound = objWasBound;
	}

	@Override
	public boolean next() {
		release();
		while (position < pairs.length) {
			long subj = pairs[position];
			long obj = pairs[position + 1];
			position += 2;
			int m = row.mark();
			boolean ok = (subjWasBound || plan.subjSlot < 0 || row.bind(plan.subjSlot, subj))
					&& (objWasBound || plan.objSlot < 0 || row.bind(plan.objSlot, obj));
			if (ok) {
				mark = m;
				return true;
			}
			row.rollback(m);
		}
		return false;
	}

	private void release() {
		if (mark >= 0) {
			row.rollback(mark);
			mark = -1;
		}
	}

	@Override
	public void close() {
		release();
	}
}

